// Validasi Pengajuan Cuti Karyawan
// Referensi: UU Cipta Kerja / PP 35/2021

const input = $input.first().json.body;

// Field wajib
const requiredFields = ['employee_id', 'nama', 'jenis_cuti', 'tanggal_mulai', 'tanggal_selesai', 'alasan', 'pengganti'];
const missingFields = requiredFields.filter(f => !input[f]);

if (missingFields.length > 0) {
  return [{
    json: {
      valid: false,
      error: `Field wajib belum diisi: ${missingFields.join(', ')}`,
      status: 'DITOLAK'
    }
  }];
}

// Jenis cuti yang diperbolehkan sesuai UU Cipta Kerja / PP 35/2021
const jenisCutiValid = {
  'cuti_tahunan': { nama: 'Cuti Tahunan', maxHari: 12, perluApproval: true },
  'cuti_sakit': { nama: 'Cuti Sakit', maxHari: 365, perluApproval: false },
  'cuti_melahirkan': { nama: 'Cuti Melahirkan', maxHari: 90, perluApproval: false },
  'cuti_besar': { nama: 'Cuti Besar', maxHari: 60, perluApproval: true },
  'izin': { nama: 'Izin', maxHari: 3, perluApproval: false }
};

const jenisCuti = input.jenis_cuti.toLowerCase();
if (!jenisCutiValid[jenisCuti]) {
  return [{
    json: {
      valid: false,
      error: `Jenis cuti tidak valid: ${input.jenis_cuti}. Pilihan: ${Object.keys(jenisCutiValid).join(', ')}`,
      status: 'DITOLAK'
    }
  }];
}

// Parse tanggal
const tanggalMulai = new Date(input.tanggal_mulai);
const tanggalSelesai = new Date(input.tanggal_selesai);

if (isNaN(tanggalMulai.getTime()) || isNaN(tanggalSelesai.getTime())) {
  return [{
    json: {
      valid: false,
      error: 'Format tanggal tidak valid. Gunakan format YYYY-MM-DD',
      status: 'DITOLAK'
    }
  }];
}

if (tanggalSelesai < tanggalMulai) {
  return [{
    json: {
      valid: false,
      error: 'Tanggal selesai harus setelah tanggal mulai',
      status: 'DITOLAK'
    }
  }];
}

// Hitung durasi cuti (exclude weekend: Sabtu & Minggu)
let totalHariKerja = 0;
let currentDate = new Date(tanggalMulai);
while (currentDate <= tanggalSelesai) {
  const dayOfWeek = currentDate.getDay();
  if (dayOfWeek !== 0 && dayOfWeek !== 6) {
    totalHariKerja++;
  }
  currentDate.setDate(currentDate.getDate() + 1);
}

const infoCuti = jenisCutiValid[jenisCuti];

// Cek auto-approval: cuti tahunan <= 3 hari
const bisaAutoApprove = (jenisCuti === 'cuti_tahunan' && totalHariKerja <= 3);

return [{
  json: {
    valid: true,
    employee_id: input.employee_id,
    nama: input.nama,
    jenis_cuti: jenisCuti,
    jenis_cuti_label: infoCuti.nama,
    tanggal_mulai: input.tanggal_mulai,
    tanggal_selesai: input.tanggal_selesai,
    total_hari_kerja: totalHariKerja,
    alasan: input.alasan,
    pengganti: input.pengganti,
    max_hari: infoCuti.maxHari,
    bisa_auto_approve: bisaAutoApprove,
    perlu_approval_manager: infoCuti.perluApproval && !bisaAutoApprove,
    tanggal_pengajuan: new Date().toISOString().split('T')[0],
    status: 'MENUNGGU'
  }
}];

// Cek sisa cuti karyawan dari Google Sheets
const pengajuan = $('Validasi Pengajuan Cuti').first().json;
const dataCuti = $input.first().json;

if (!dataCuti || !dataCuti.employee_id) {
  return [{
    json: {
      ...pengajuan,
      saldo_cukup: false,
      error: `Data karyawan ${pengajuan.employee_id} tidak ditemukan di sheet saldo cuti`,
      sisa_cuti: 0
    }
  }];
}

// Ambil sisa cuti sesuai jenis
const fieldMap = {
  'cuti_tahunan': 'sisa_cuti_tahunan',
  'cuti_sakit': 'sisa_cuti_sakit',
  'cuti_melahirkan': 'sisa_cuti_melahirkan',
  'cuti_besar': 'sisa_cuti_besar',
  'izin': 'sisa_izin'
};

const field = fieldMap[pengajuan.jenis_cuti];
const sisaCuti = parseInt(dataCuti[field] || '0', 10);
const saldoCukup = sisaCuti >= pengajuan.total_hari_kerja;

// Tentukan apakah bisa auto-approve
const autoApprove = pengajuan.bisa_auto_approve && saldoCukup;

return [{
  json: {
    ...pengajuan,
    sisa_cuti: sisaCuti,
    sisa_setelah: sisaCuti - pengajuan.total_hari_kerja,
    saldo_cukup: saldoCukup,
    auto_approve: autoApprove,
    departemen: dataCuti.departemen || '',
    email_karyawan: dataCuti.email || '',
    email_manager: dataCuti.email_manager || '',
    telegram_chat_id: dataCuti.telegram_chat_id || '',
    manager_nama: dataCuti.manager_nama || ''
  }
}];

